@dataclass
class Depends:
    dependency: Optional[Callable[..., Any]] = None
    use_cache: bool = True
    scope: Union[Literal["function", "request"], None] = None

    def __hash__(self) -> int:
        try:
            dependency_hash = hash(self.dependency)
        except TypeError:
            # Callable instances can define equality without being hashable.
            dependency_hash = 0
        return hash((dependency_hash, self.use_cache, self.scope))


@dataclass
class Security(Depends):
    scopes: Optional[Sequence[str]] = None

    def __hash__(self) -> int:
        return hash((super().__hash__(), tuple(self.scopes or ())))
